import{_ as t,o as a,c as o,a2 as d}from"./chunks/framework.CyZTVJbV.js";const v=JSON.parse('{"title":"AI-LLM advanced III testing — v0.5 8 axis × 4 provider = 32 cell advanced III grid + real-driver env-gate (SSOT)","description":"","frontmatter":{},"headers":[],"relativePath":"concepts/ai-llm-advanced-III-testing.md","filePath":"concepts/ai-llm-advanced-III-testing.md"}'),i={name:"concepts/ai-llm-advanced-III-testing.md"};function n(r,e,s,c,l,h){return a(),o("div",null,[...e[0]||(e[0]=[d('<h1 id="ai-llm-advanced-iii-testing-—-v0-5-8-axis-×-4-provider-32-cell-advanced-iii-grid-real-driver-env-gate-ssot" tabindex="-1">AI-LLM advanced III testing — v0.5 8 axis × 4 provider = 32 cell advanced III grid + real-driver env-gate (SSOT) <a class="header-anchor" href="#ai-llm-advanced-iii-testing-—-v0-5-8-axis-×-4-provider-32-cell-advanced-iii-grid-real-driver-env-gate-ssot" aria-label="Permalink to &quot;AI-LLM advanced III testing — v0.5 8 axis × 4 provider = 32 cell advanced III grid + real-driver env-gate (SSOT)&quot;">​</a></h1><p>kiwa&#39;s v1.40-1 ai-llm v0.5 package (<code>@kiwa/ai-llm</code> v0.5.0) covers <strong>8 advanced III axes</strong> that model the deepening LLM production posture of a real product stack beyond the v0.4 advanced axes (prompt injection + hallucination + LLM eval + guardrails + RAG advanced + agent orchestration + fine-tuning eval + cost / latency SLA) — multi-agent orchestration (CrewAI + LangGraph supervisor) + agent swarm (role-based + PBFT-lite consensus) + code interpreter (sandboxed REPL + tool use + rollback) + fine-tuning pipeline (dataset + RLHF/DPO + eval loop + drift) + LLM ops (model registry + rollout + A/B + canary + shadow) + prompt engineering advanced (CoT + few-shot + caching + versioning) + RAG III (GraphRAG + agentic + self-querying + parent document) + cost optimization (batch API + prompt compression + model cascade + semantic cache). This concept doc is the SSOT for those 8 advanced III axes; the tutorials (85-87) and dogfood apps (v1.40-2/3/4) are the concrete implementations.</p><p>The v0.5 grid is orthogonal to the v0.4 advanced grid — the v0.4 advanced grid (<code>AI_LLM_ADV_FIDELITY_GRID</code> conceptual name, but implemented through the same <code>AI_LLM_AXIS_TO_EVENTS</code>) covers the &quot;run one agent, decide one answer, emit one event&quot; primitive across 4 provider (<code>anthropic</code> / <code>openai</code> / <code>vercel-ai</code> / <code>langchain</code>), and the v0.5 advanced III grid extends the same 4 provider matrix with the &quot;orchestrate multiple agents, interpret code in a sandbox, run a fine-tuning pipeline, manage the model lifecycle in production, walk a GraphRAG index&quot; primitives. Read the <code>ai-llm-real-driver-testing.md</code> concept doc first for the v0.4 advanced grid, then read this doc for the v0.5 advanced III grid.</p><h2 id="the-8-advanced-iii-axes-grid" tabindex="-1">The 8 advanced III axes grid <a class="header-anchor" href="#the-8-advanced-iii-axes-grid" aria-label="Permalink to &quot;The 8 advanced III axes grid&quot;">​</a></h2><p>The 8 axes are cover-oriented — each one names a real-world failure surface every non-trivial production LLM stack hits after the v0.4 advanced axes land.</p><table tabindex="0"><thead><tr><th>Axis</th><th>Real-world failure it catches</th><th>v0.5 API</th></tr></thead><tbody><tr><td>Multi-agent orchestration</td><td>&quot;The supervisor delegated the same task to <code>worker A</code> twice because the round counter was reset on session save, and the LangGraph node walk never terminated because the terminal node&#39;s outgoing edge pointed at a visited ancestor&quot; (no round-robin invariant on delegation, no visited-set on graph transition, no terminal-node record)</td><td><code>startMaoSession</code> / <code>assembleCrew</code> / <code>delegateBySupervisor</code> / <code>transitionGraph</code> / <code>completeRound</code></td></tr><tr><td>Agent swarm</td><td>&quot;The swarm consensus fired on a 5-vs-5 split because the majority check was <code>&gt;=</code> instead of <code>&gt;</code>, and the Byzantine fault check let 4 faulty out of 10 through because the threshold was <code>0.5</code> instead of the PBFT-lite <code>0.34</code>&quot; (no strict-majority gate, no <code>1 - threshold</code> honest-ratio invariant, no null-winner on a split)</td><td><code>startSwarmSession</code> / <code>assignRoles</code> / <code>allocateTasks</code> / <code>reachConsensus</code> / <code>tolerateByzantine</code></td></tr><tr><td>Code interpreter</td><td>&quot;The rollback popped 3 executions but the memory snapshot was one step stale because the snapshot was taken after the assignment instead of before&quot; (no snapshot-before-assign invariant, no per-execution memory snapshot, no tool-call <code>ok=false</code> on <code>unknown</code> tool name)</td><td><code>startCiSession</code> / <code>startSandbox</code> / <code>executeCode</code> / <code>useTool</code> / <code>rollback</code></td></tr><tr><td>Fine-tuning pipeline</td><td>&quot;The RLHF policy update landed on a non-deterministic delta because the mean was computed over a shuffled batch and the drift detector fired on a <code>NaN</code> because the baseline was never pinned&quot; (no <code>learningRate * meanReward</code> invariant, no first-call baseline snapshot, no <code>Math.abs(delta) &gt;= threshold</code> gate)</td><td><code>startFtpSession</code> / <code>prepareDataset</code> / <code>stepRlhf</code> / <code>runEvalLoop</code> / <code>detectDrift</code></td></tr><tr><td>LLM ops</td><td>&quot;The A/B evaluator picked the variant with 5 samples over the one with 500 samples because <code>minSamples</code> was not enforced, and the canary promotion rewrote the registry <code>active</code> bit before the error-rate check ran&quot; (no <code>minSamples</code> filter, no <code>errorRate &lt;= threshold</code> gate, no post-promotion registry rewrite)</td><td><code>startOpsSession</code> / <code>updateRegistry</code> / <code>advanceRollout</code> / <code>evaluateAb</code> / <code>promoteCanary</code> / <code>compareShadow</code></td></tr><tr><td>Prompt engineering advanced</td><td>&quot;The prompt cache hit rate was measured on a version drift because <code>pinVersion</code> was called after <code>cachePrompt</code> instead of before, and the few-shot picker returned the first-in-array instead of the top-by-score because the pool was iterated in insertion order&quot; (no strict <code>semver+hash</code> pin, no top-k sort by score descending, no cache-hit accounting)</td><td><code>startPeaSession</code> / <code>expandChainOfThought</code> / <code>selectFewShot</code> / <code>cachePrompt</code> / <code>pinVersion</code></td></tr><tr><td>RAG III</td><td>&quot;The GraphRAG traversal never terminated because the <code>maxHops</code> guard was off by one, and the agentic step decided <code>answer</code> on a <code>confidence: 0.3</code> because the threshold comparison was <code>&gt;</code> instead of <code>&gt;=</code>&quot; (no <code>maxHops</code> decrement in BFS, no <code>confidence &gt;= threshold</code> invariant, no chunk-to-parent lookup on cold miss)</td><td><code>startRag3Session</code> / <code>traverseGraph</code> / <code>stepAgentic</code> / <code>selfQuery</code> / <code>expandParent</code></td></tr><tr><td>Cost optimization</td><td>&quot;The model cascade escalated to the top tier on every request because the confidence threshold was set on the top tier instead of the bottom, and the batch savings estimate was 2x instead of 0.5x because the pricing table was misread&quot; (no cheapest-tier-first sort, no 0.5x savings ratio, no cache backfill on cold miss)</td><td><code>startCoSession</code> / <code>submitBatch</code> / <code>compressPrompt</code> / <code>stepCascade</code> / <code>lookupSemanticCache</code></td></tr></tbody></table><p>Each axis has 3 shapes — a mock-only path (fast inner loop, ms scale), a real-driver path (<code>KIWA_MODE=real</code> + real LangGraph / CrewAI / Docker Python REPL / Redis + Postgres model registry, seconds scale), and a fidelity assertion that the two produce the same output. Tutorial 85 covers the multi-agent + swarm end-to-end chain (crew → delegate → graph → round → roles → tasks → consensus → Byzantine), tutorial 86 covers the code interpreter + fine-tuning pipeline chain (sandbox → execute → tool → rollback → dataset → RLHF → eval → drift), tutorial 87 covers the LLM ops + prompt engineering + RAG III + cost optimization chain (registry → rollout → A/B → canary → shadow → CoT → few-shot → cache → version → graph → agentic → self-query → parent → batch → compress → cascade → semantic-cache).</p><h2 id="the-4-provider-×-8-axis-32-cell-grid" tabindex="-1">The 4-provider × 8-axis = 32 cell grid <a class="header-anchor" href="#the-4-provider-×-8-axis-32-cell-grid" aria-label="Permalink to &quot;The 4-provider × 8-axis = 32 cell grid&quot;">​</a></h2><p>Every provider covers every axis. The mock shapes are provider-neutral (the API surface is the same across <code>anthropic</code> + <code>openai</code> + <code>vercel-ai</code> + <code>langchain</code>), the emitted event dialects are provider-specific (<code>anthropic.mao.crew_assembled</code> vs. <code>openai.mao.crew_assembled</code> vs. <code>vercel-ai.mao.crew_assembled</code> vs. <code>langchain.mao.crew_assembled</code>), and the advanced III fidelity harness reports the coverage explicitly through <code>collectFidelityCoverage()</code> walking all 16 axes (v0.4 8 + v0.5 8).</p><table tabindex="0"><thead><tr><th>Provider</th><th>Multi-agent</th><th>Swarm</th><th>Code interp</th><th>Fine-tune pipe</th><th>LLM ops</th><th>Prompt eng adv</th><th>RAG III</th><th>Cost opt</th></tr></thead><tbody><tr><td>anthropic</td><td>implemented</td><td>implemented</td><td>implemented</td><td>implemented</td><td>implemented</td><td>implemented</td><td>implemented</td><td>implemented</td></tr><tr><td>openai</td><td>implemented</td><td>implemented</td><td>implemented</td><td>implemented</td><td>implemented</td><td>implemented</td><td>implemented</td><td>implemented</td></tr><tr><td>vercel-ai</td><td>implemented</td><td>implemented</td><td>implemented</td><td>implemented</td><td>implemented</td><td>implemented</td><td>implemented</td><td>implemented</td></tr><tr><td>langchain</td><td>implemented</td><td>implemented</td><td>implemented</td><td>implemented</td><td>implemented</td><td>implemented</td><td>implemented</td><td>implemented</td></tr></tbody></table><p>The v0.5 advanced III grid is fully covered — every provider implements every axis because the semantics are runtime-agnostic. That is what makes cross-provider reuse (a multi-agent workflow that runs under anthropic + openai + vercel-ai + langchain without change) even possible. The neutral event names live in the v0.5 <code>types.ts</code> SSOT and the per-provider dialect table is a static lookup — a new provider drops into the same shape.</p><h3 id="why-the-advanced-iii-grid-is-fully-covered" tabindex="-1">Why the advanced III grid is fully covered <a class="header-anchor" href="#why-the-advanced-iii-grid-is-fully-covered" aria-label="Permalink to &quot;Why the advanced III grid is fully covered&quot;">​</a></h3><p>anthropic + openai + vercel-ai + langchain converged on the same neutral events at the &quot;orchestrate an LLM call chain, decide an outcome, emit an event&quot; primitive — the &quot;multi-agent + code-interpreter + fine-tuning + ops + prompt-engineering + GraphRAG + cost-optimization&quot; shape is the same across all 4 providers, even though the wire encodings differ (Anthropic Messages tool-use vs. OpenAI Assistants API vs. Vercel AI SDK <code>generateText</code> vs. LangChain <code>RunnableSequence</code>). The <code>providerEventName(target, neutralEvent)</code> mapping table is the single point where the 4 dialects diverge; everything upstream stays neutral. The v1.40 advanced III fidelity grid at 32/32 = 100 % implemented reflects that convergence at the &quot;advanced LLM production&quot; level. Combined with the v0.4 32-cell advanced grid, the total v0.4 + v0.5 fidelity harness now walks 64 cells (4 provider × 16 axis) in one <code>collectFidelityCoverage()</code> call.</p><h2 id="the-kiwa-mode-real-env-gate-contract-for-the-advanced-iii-grid" tabindex="-1">The <code>KIWA_MODE=real</code> env-gate contract for the advanced III grid <a class="header-anchor" href="#the-kiwa-mode-real-env-gate-contract-for-the-advanced-iii-grid" aria-label="Permalink to &quot;The `KIWA_MODE=real` env-gate contract for the advanced III grid&quot;">​</a></h2><p><code>skipUnlessReal(provider, env)</code> returns <code>{ skip: false, reason: &#39;KIWA_MODE=real + required env present — real driver&#39; }</code> when <code>env.KIWA_MODE === &#39;real&#39;</code> and the required env for that provider is set, and <code>{ skip: true, reason: &#39;KIWA_MODE!=real (got &quot;unset&quot;) — mock driver&#39; }</code> otherwise. A test that respects the contract combines the gate with a required-env presence check — the dogfood apps use this at each <code>describe.skipIf(gate.skip)</code> block. The v0.5 advanced III axes reuse the same real-driver gate as the v0.4 advanced axes — no new env variable is introduced. The per-axis dogfood app pins the required backend URL (<code>KIWA_LANGGRAPH_URL</code> / <code>KIWA_CI_SANDBOX_URL</code> / <code>KIWA_OPS_REGISTRY_URL</code>) on top of the shared <code>ANTHROPIC_API_KEY</code> + <code>KIWA_LLM_BUDGET_USD</code> gate.</p><p>Per-provider required-env mapping stays the same as v0.4.</p><ul><li><strong>anthropic</strong> → <code>KIWA_MODE</code> + <code>ANTHROPIC_API_KEY</code> + <code>KIWA_LLM_BUDGET_USD</code> (Anthropic Messages API endpoint)</li><li><strong>openai</strong> → <code>KIWA_MODE</code> + <code>OPENAI_API_KEY</code> + <code>KIWA_LLM_BUDGET_USD</code> (OpenAI Chat Completions + Assistants API)</li><li><strong>vercel-ai</strong> → <code>KIWA_MODE</code> + <code>OPENAI_API_KEY</code> (Vercel AI SDK routes through the underlying provider) + <code>KIWA_LLM_BUDGET_USD</code></li><li><strong>langchain</strong> → <code>KIWA_MODE</code> + <code>ANTHROPIC_API_KEY</code> (LangChain runnable sequence over Anthropic) + <code>KIWA_LLM_BUDGET_USD</code></li></ul><p>Per-dogfood-app required backend URL (on top of the provider gate above).</p><ul><li><strong>dogfood-llm-multi-agent-swarm-app</strong> → <code>KIWA_LANGGRAPH_URL</code> + <code>KIWA_CREWAI_URL</code> (real LangGraph + CrewAI SDKs)</li><li><strong>dogfood-llm-code-interpreter-app</strong> → <code>KIWA_CI_SANDBOX_URL</code> (Docker-isolated Python REPL, e.g. <code>http://localhost:8100</code>)</li><li><strong>dogfood-llm-ops-registry-app</strong> → <code>KIWA_OPS_REGISTRY_URL</code> (Redis + Postgres model registry, e.g. <code>http://localhost:8200</code>)</li></ul><h2 id="kiwa-llm-budget-usd-budget-guard-unchanged-from-v0-4" tabindex="-1"><code>KIWA_LLM_BUDGET_USD</code> budget guard (unchanged from v0.4) <a class="header-anchor" href="#kiwa-llm-budget-usd-budget-guard-unchanged-from-v0-4" aria-label="Permalink to &quot;`KIWA_LLM_BUDGET_USD` budget guard (unchanged from v0.4)&quot;">​</a></h2><p>The v0.5 axes reuse the same budget guard as v0.4. <code>chargeBudget(env, usd)</code> decrements the caller-supplied budget and throws when the remaining balance falls below zero. Every real-driver call goes through <code>chargeBudget</code> before hitting the wire so a runaway multi-agent loop cannot silently rack up an $80 bill. The mock path never touches the guard (mock cost is zero) so the inner-loop iteration stays free of budget noise.</p><h2 id="the-16-axis-fidelity-harness-v0-4-8-v0-5-8-combined" tabindex="-1">The 16-axis fidelity harness (v0.4 8 + v0.5 8 combined) <a class="header-anchor" href="#the-16-axis-fidelity-harness-v0-4-8-v0-5-8-combined" aria-label="Permalink to &quot;The 16-axis fidelity harness (v0.4 8 + v0.5 8 combined)&quot;">​</a></h2><p><code>collectFidelityCoverage()</code> walks the full 16-axis grid and returns a per-cell <code>{ provider, axis, implemented, missingEvents }</code> record so a CI job can assert <code>rows.every(r =&gt; r.implemented)</code> in one line. The <code>AI_LLM_AXIS_TO_EVENTS</code> table has 16 entries after v0.5 lands — the 4 neutral events per axis floor (asserted in the fidelity test) is preserved for the 8 new v0.5 axes.</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { collectFidelityCoverage } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;@kiwa/ai-llm&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> cov</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> collectFidelityCoverage</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">console.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">log</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(cov.rows.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">length</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">); </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 64 (4 provider × 16 axis)</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">console.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">log</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(cov.rows.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">every</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">((</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">r</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> r.implemented)); </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// true after v0.5 lands</span></span></code></pre></div><p>The 64-row grid is the single point of truth for the &quot;is a provider × axis pair covered?&quot; question — a new dogfood app that adds a new provider walks the same table without touching the axis list.</p><h2 id="the-v1-40-pair-深度-4-段-record-unprecedented-in-kiwa-history" tabindex="-1">The v1.40 pair 深度 4 段 record (unprecedented in kiwa history) <a class="header-anchor" href="#the-v1-40-pair-深度-4-段-record-unprecedented-in-kiwa-history" aria-label="Permalink to &quot;The v1.40 pair 深度 4 段 record (unprecedented in kiwa history)&quot;">​</a></h2><p>v0.5 is the 10th 縦深化 pair in kiwa history and the <strong>first pair to reach depth 4 (v1.12 → v1.15 → v1.38 → v1.40)</strong>. Previous deepest pair depths were 3 (Payment v1.14→v1.19→v1.33 and Observability v1.16→v1.20→v1.35). The v1.40 milestone establishes a new record and validates the 縦深化 methodology at unprecedented depth — the same 4-provider × 8-axis fidelity harness template applies at each depth without change, and the 深化 process (v0.1 base → v0.4 advanced → v0.5 advanced III) is idempotent under scale.</p><p>Combined with the v1.38 v0.4 advanced grid (8 axis × 4 provider = 32 cell) + the v1.40 v0.5 advanced III grid (8 axis × 4 provider = 32 cell), the ai-llm package now covers 16 axes × 4 provider = 64 cells of production LLM shape in one package with one fidelity harness — the broadest single-package matrix in the kiwa ecosystem.</p>',28)])])}const g=t(i,[["render",n]]);export{v as __pageData,g as default};
